import { describe, it, expect } from "vitest";
import { runScenario } from "./claim-office.js";

describe("MHPCO Claim Office", () => {
  // --- Quote: base premiums, simplest first ---
  it("empty item list → premium 5 G (only the processing fee)", () => {
    const result = runScenario({
      customer: { yearsWithMHPCO: 0 },
      steps: [{ op: "quote", items: [] }],
    });

    expect(result).toEqual({ results: [{ premium: 5 }] });
  });
  it("a plain sword → premium 115 G (100 base + 10 first insurance + 5 fee)", () => {
    const result = runScenario({
      customer: { yearsWithMHPCO: 0 },
      steps: [
        { op: "quote", items: [{ type: "sword", material: "steel", enchantment: 3, cursed: false }] },
      ],
    });

    expect(result).toEqual({ results: [{ premium: 115 }] });
  });
  it.todo("a plain amulet → premium 71 G (60 base + 6 first insurance + 5 fee)");
  it.todo("a plain staff → premium 93 G (80 base + 8 first insurance + 5 fee)");
  it.todo("a plain potion → premium 49 G (40 base + 4 first insurance + 5 fee)");
  it.todo("a single rune → base premium 25 G");

  // --- Building block of 3 alike components ---
  it.todo("2 runes → 50 G base premium");
  it.todo("3 runes → 60 G base premium (block applies)");
  it.todo("4 runes → 100 G base premium (no block — block requires exactly 3)");
  it.todo("7 runes → 175 G base premium");

  // --- "Alike" components (❓ same type, not same family) ---
  it.todo("2 runes + 1 moonstone → 75 G base premium (no block: different types)");
  it.todo("3 runes + 3 moonstones → 120 G base premium (two separate blocks)");

  // --- Premium modifiers in isolation ---
  it.todo("cursed sword adds a 50 % risk surcharge on the item base premium");
  it.todo("sword with enchantment 5 adds a 30 % high-enchantment surcharge (threshold)");
  it.todo("sword with enchantment 4 gets no high-enchantment surcharge");
  it.todo("cursed sword with enchantment 5 gets both surcharges");
  it.todo("customer with exactly 2 years with MHPCO receives the 20 % loyalty discount");
  it.todo("customer with 1 year with MHPCO receives no loyalty discount");
  it.todo("every quote carries the 10 % initial assessment surcharge (first insurance)");
  it.todo("second quote in a scenario receives the 15 % follow-up contract discount");

  // --- Modifier scope on multi-item policies (❓ item-specific vs policy-wide) ---
  it.todo(
    "cursed sword (100 G) + plain amulet (60 G) → base 160 G, curse adds 50 G → 210 G before further modifiers and fee",
  );

  // --- Rounding in the MHPCO's favor ---
  it.todo("a premium calculation that yields 197.5 G → final premium 198 G (rounded up)");
  it.todo("a payout calculation that yields 350.5 G → final payout 350 G (rounded down)");

  // --- Integration examples ---
  it.todo("newcomer with a cursed sword (0 years, steel, enchantment 3) → premium 165 G");
  it.todo(
    "long-standing customer's second contract (3 years, cursed sword enchantment 7) → premium 160 G",
  );

  // --- Claims: standard reimbursement ---
  it.todo("regular sword (steel, enchantment 3), damage 500 G → payout 400 G");
  it.todo("damage to a rune (insurance value 250 G), damage 200 G → payout 100 G");

  // --- Claims: special clauses ---
  it.todo("dragon-material sword, enchantment 5, damage 800 G → payout 700 G (full, then deductible)");
  it.todo("steel sword, enchantment 9, damage 1000 G → payout 400 G (50 % first, then deductible)");
  it.todo("dragon-material sword, enchantment 9, damage 1000 G → payout 400 G (50 % rule wins)");
  it.todo("dragon-material sword with exactly enchantment 8, damage 1000 G → payout 400 G");

  // --- Deductible per damage event ---
  it.todo(
    "dragon attack damages a sword (500 G) and an amulet (300 G) → payout 600 G (deductible once per damaged item)",
  );

  // --- Insurance sum and cap ---
  it.todo("a policy covering a sword and an amulet → insurance sum 1600 G, cap 3200 G");
  it.todo("a policy covering two swords → insurance sum 2000 G, cap 4000 G");
  it.todo("a cursed sword → cap 2000 G (premium modifiers do not raise the cap)");
  it.todo("a policy covering a sword and 3 runes (a block) → insurance sum 1750 G, cap 3500 G");

  // --- Cap exhaustion across successive claims ---
  it.todo("sword (cap 2000 G), first claim of 1500 G → payout 1400 G, remainingCap 600 G");
  it.todo("sword (cap 2000 G), second claim of 1500 G → payout 600 G, remainingCap 0 G");

  // --- Multiple items of the same type (❓ two swords) ---
  it.todo(
    "two swords insured, damages contains two sword entries → each treated as a separate damage with its own deductible",
  );
  it.todo(
    "more damage entries of a type than the policy covers (two sword damages, one sword insured) → error",
  );

  // --- Error cases ---
  it.todo("quote includes an item with an unknown type (broomstick) → error");
  it.todo("claim references an item not part of the policy (amulet damaged, only sword insured) → error");
  it.todo("claim references a damage entry with an unknown item type → error");
  it.todo("claim contains a damage entry with amount -200 → error");

  // --- CLI ---
  it.todo("CLI reads a scenario from stdin and writes {results: [...]} to stdout (schema example)");
  it.todo("CLI exits with a non-zero status code and writes an error to stderr on an unknown item type");
  it.todo("CLI exits with a non-zero status code and writes an error to stderr on an invalid claim");
});

