const roundPremium = (amount: number): number => Math.ceil(Number(amount.toFixed(6)));

const quotePremium = (items: Item[]): number => {
  const basePremium = items.length === 0 ? 0 : 100;
  return roundPremium(basePremium * (1 + FIRST_INSURANCE_SURCHARGE) + PROCESSING_FEE);
};

