  it.todo("a policy covering two swords → insurance sum 2000 G, cap 4000 G");
  it.todo("a cursed sword → cap 2000 G (premium modifiers do not raise the cap)");
  it.todo("a policy covering a sword and 3 runes (a block) → insurance sum 1750 G, cap 3500 G");

  // --- Cap exhaustion across successive claims ---
  it.todo("sword (cap 2000 G), first claim of 1500 G → payout 1400 G, remainingCap 600 G");
  it.todo("sword (cap 2000 G), second claim of 1500 G → payout 600 G, remainingCap 0 G");

  // --- Multiple items of the same type (❓ two swords) ---
  it.todo(
    "two swords insured, damages contains two sword entries → each treated as a separate damage with its own deductible",
  );
  it.todo(
    "more damage entries of a type than the policy covers (two sword damages, one sword insured) → error",
  );

  // --- Error cases ---
  it.todo("quote includes an item with an unknown type (broomstick) → error");
  it.todo("claim references an item not part of the policy (amulet damaged, only sword insured) → error");
  it.todo("claim references a damage entry with an unknown item type → error");
  it.todo("claim contains a damage entry with amount -200 → error");

  // --- CLI ---
  it.todo("CLI reads a scenario from stdin and writes {results: [...]} to stdout (schema example)");
  it.todo("CLI exits with a non-zero status code and writes an error to stderr on an unknown item type");
  it.todo("CLI exits with a non-zero status code and writes an error to stderr on an invalid claim");
});

