  it.todo("second quote in a scenario receives the 15 % follow-up contract discount");

  // --- Modifier scope on multi-item policies (❓ item-specific vs policy-wide) ---
  it.todo(
    "cursed sword (100 G) + plain amulet (60 G) → base 160 G, curse adds 50 G → 210 G before further modifiers and fee",
  );

  // --- Rounding in the MHPCO's favor ---
  it.todo("a premium calculation that yields 197.5 G → final premium 198 G (rounded up)");
  it.todo("a payout calculation that yields 350.5 G → final payout 350 G (rounded down)");

  // --- Integration examples ---
  it.todo("newcomer with a cursed sword (0 years, steel, enchantment 3) → premium 165 G");
  it.todo(
    "long-standing customer's second contract (3 years, cursed sword enchantment 7) → premium 160 G",
  );

  // --- Claims: standard reimbursement ---
  it.todo("regular sword (steel, enchantment 3), damage 500 G → payout 400 G");
  it.todo("damage to a rune (insurance value 250 G), damage 200 G → payout 100 G");

  // --- Claims: special clauses ---
  it.todo("dragon-material sword, enchantment 5, damage 800 G → payout 700 G (full, then deductible)");
  it.todo("steel sword, enchantment 9, damage 1000 G → payout 400 G (50 % first, then deductible)");
  it.todo("dragon-material sword, enchantment 9, damage 1000 G → payout 400 G (50 % rule wins)");
