  it.todo("a policy covering two swords → insurance sum 2000 G, cap 4000 G");
  it.todo("a cursed sword → cap 2000 G (premium modifiers do not raise the cap)");
  it.todo("a policy covering a sword and 3 runes (a block) → insurance sum 1750 G, cap 3500 G");

  // --- Cap exhaustion across successive claims ---
