export interface Scenario {
  customer: { yearsWithMHPCO: number };
  steps: Step[];
}

export type Step = QuoteStep | ClaimStep;

export interface QuoteStep {
  op: "quote";
  items: Item[];
}

export interface Item {
  type: string;
  material?: string;
  enchantment?: number;
  cursed?: boolean;
}

export interface ClaimStep {
  op: "claim";
  policy: number;
  incident: Incident;
}

export interface Incident {
  cause: string;
  damages: Damage[];
}

export interface Damage {
  itemType: string;
  amount: number;
}

export type Result = { premium: number } | { payout: number; remainingCap: number };

const sum = (amounts: number[]): number => amounts.reduce((total, a) => total + a, 0);

const PROCESSING_FEE = 5;

const FIRST_INSURANCE_SURCHARGE_RATE = 0.1;

/** Rounds up in the MHPCO's favor, ignoring binary floating-point noise. */
const roundPremium = (amount: number): number => Math.ceil(Number(amount.toFixed(6)));

/** The closed set of insurable item types, each with its base premium in gold. */
const BASE_PREMIUMS = {
  sword: 100,
  amulet: 60,
  staff: 80,
  potion: 40,
  rune: 25,
  moonstone: 25,
} as const satisfies Record<string, number>;

export type ItemType = keyof typeof BASE_PREMIUMS;

const basePremiumOf = (item: Item): number => BASE_PREMIUMS[item.type as ItemType];

const BLOCK_SIZE = 3;
const BLOCK_BASE_PREMIUM = 60;

/** Groups items by type; "alike" means same type, not same family. */
const groupByType = (items: Item[]): Item[][] => {
  const types = [...new Set(items.map((item) => item.type))];
  return types.map((type) => items.filter((item) => item.type === type));
};

const COMPONENT_TYPES = new Set<string>(["rune", "moonstone"]);

const isComponent = (item: Item): boolean => COMPONENT_TYPES.has(item.type);

/** Three alike components form a block, priced at a special base premium. */
const basePremiumOfGroup = (group: Item[]): number =>
  group.length === BLOCK_SIZE && group.every(isComponent)
    ? BLOCK_BASE_PREMIUM
    : sum(group.map(basePremiumOf));

const totalBasePremium = (items: Item[]): number =>
  sum(groupByType(items).map(basePremiumOfGroup));

const CURSE_SURCHARGE_RATE = 0.5;

const HIGH_ENCHANTMENT_SURCHARGE_RATE = 0.3;
const HIGH_ENCHANTMENT_THRESHOLD = 5;

const isCursed = (item: Item): boolean => item.cursed === true;

const isHighlyEnchanted = (item: Item): boolean =>
  (item.enchantment ?? 0) >= HIGH_ENCHANTMENT_THRESHOLD;

const itemSurchargeRate = (item: Item): number =>
  (isCursed(item) ? CURSE_SURCHARGE_RATE : 0) +
  (isHighlyEnchanted(item) ? HIGH_ENCHANTMENT_SURCHARGE_RATE : 0);

/**
 * Item-specific surcharges apply to the affected item's own base premium,
 * unlike policy-wide modifiers which apply to the policy's total base premium.
 *
 * NOTE: this uses each item's ungrouped base premium, so a cursed component
 * inside a 3-alike block is surcharged against its own 25 G rather than its
 * share of the block's 60 G. No test covers that combination yet; the choice
 * is unverified, not deliberate.
 */
const itemSurcharges = (items: Item[]): number =>
  sum(items.map((item) => basePremiumOf(item) * itemSurchargeRate(item)));

/** Policy-wide modifiers apply to the policy's base premium, not to the item surcharges. */
const policyModifiers = (basePremium: number): number =>
  basePremium * FIRST_INSURANCE_SURCHARGE_RATE;

const quotePremium = (items: Item[]): number => {
  const basePremium = totalBasePremium(items);
  const premiumBeforeFee =
    basePremium + itemSurcharges(items) + policyModifiers(basePremium);
  return roundPremium(premiumBeforeFee + PROCESSING_FEE);
};

const runStep = (step: Step): Result => {
  if (step.op === "quote") return { premium: quotePremium(step.items) };
  throw new Error(`Unsupported step: ${step.op}`);
};

export const runScenario = (scenario: Scenario): { results: Result[] } => {
  return { results: scenario.steps.map(runStep) };
};

