const INSURANCE_VALUES: Record<ItemType, number> = {
  sword: 1000,
  amulet: 600,
  staff: 800,
  potion: 400,
  rune: 250,
  moonstone: 250,
};

const insuranceValueOf = (item: Item): number => INSURANCE_VALUES[item.type as ItemType];

const DEDUCTIBLE = 100;
const CAP_MULTIPLIER = 2;

/** Rounds down in the MHPCO's favor. */
const roundPayout = (amount: number): number => Math.floor(Number(amount.toFixed(6)));

interface Policy {
  items: Item[];
  remainingCap: number;
}

const openPolicy = (items: Item[]): Policy => ({
  items,
  remainingCap: sum(items.map(insuranceValueOf)) * CAP_MULTIPLIER,
});

const reimbursement = (damage: Damage): number => damage.amount - DEDUCTIBLE;

const settleClaim = (policy: Policy, incident: Incident): Result => {
  const desired = sum(incident.damages.map(reimbursement));
  const payout = roundPayout(Math.min(desired, policy.remainingCap));
  policy.remainingCap -= payout;
  return { payout, remainingCap: policy.remainingCap };
};

export const runScenario = (scenario: Scenario): { results: Result[] } => {
  const policies = new Map<number, Policy>();
  let quotesSoFar = 0;

  const results = scenario.steps.map((step, stepIndex) => {
    if (step.op === "quote") {
      const premium = quotePremium(step.items, scenario.customer, quotesSoFar > 0);
      quotesSoFar += 1;
      policies.set(stepIndex, openPolicy(step.items));
      return { premium };
    }
    const policy = policies.get(step.policy);
    if (policy === undefined) throw new Error(`No policy at step ${step.policy}`);
    return settleClaim(policy, step.incident);
  });

  return { results };
};

